public class METCrossDockTransferOrderProcessor_TransferOrder extends METCrossDockTransferOrderProcessorBase
{
    InventTransferTable inventTransferTable;
    METInventTransferTableExt metInventTransferTable;

    InventTransferLine inventTransferLine;
    METInventTransferLine metInventTransferLine;

}

Method.Source:
/// <summary>
/// Determine if this TO is to supply a transfer order
/// </summary>
/// <returns>Yes, if the TO is for a transfer order, otherwise, No</returns>
protected NoYes isFinalLegTO()
{
    NoYes ret = super();

    ret = NoYes::Yes;

    return ret;
}

/// <summary>
/// Initialize transfer class objects
/// </summary>
/// <param name = "_sourceRecord">Sorce transaction record</param>
public void init(Common _sourceRecord)
{
    inventTransferTable = _sourceRecord;
}

/// <summary>
/// Create cross dock transfer order
/// </summary>
/// <param name = "_record">Source record</param>
public void CreateTransferOrder()
{
    metInventTransferTable = METInventTransferTableExt::findByTransferId(inventTransferTable.TransferId);

    InventDim inventDim;

    ttsbegin;
    while select inventTransferLine
        order by metInventTransferLine.SupplyingWarehouse
        where inventTransferLine.TransferId == inventTransferTable.TransferId
        join metInventTransferLine where metInventTransferLine.InventTransferLine == inventTransferLine.RecId
        && metInventTransferLine.OrderExtractStatus != METOrderExtractStatus::Extracted
    {
        this.CreateTransferOrderLine();
    }

    metInventTransferTable.selectForUpdate(true);
    metInventTransferTable.OrderExtractStatus = METOrderExtractStatus::Extracted;
    metInventTransferTable.update();

    ttscommit;

    //super();
}

