/// <summary>
/// Sets the reference data
/// </summary>
/// <param name = "_transLineExt"><t>METInventTransferLine</t> table buffer</param>
protected void setSourceLineReference(METInventTransferLine _transLineExt)
{
    _transLineExt.TransferOrderNumber = this.getSoruceId();
    _transLineExt.TransferLineTransId = this.getSourceTransId();
}

