/// <summary>
///
/// </summary>
/// <param name = "_transferLine"></param>
public void updateMarking(InventTransferLine _transferLine)
{
    if (!PdsGlobal::pdsIsCWItem(_transferLine.ItemId))
    {
        ttsbegin;

        InventTransferLine transLine = InventTransferLine::findTransIdReceive(inventTransferLine.InventTransId);

        if (!transLine.RecId)
        {
            return;
        }

        InventTransOriginId sourceTransferLineTransOriginId = InventTransOrigin::findByInventTransId(transLine.InventTransIdReceive).RecId;
        InventTransOriginId transferLineTransOriginId = InventTransOrigin::findByInventTransId(_transferLine.InventTransIdReceive).RecId;

        InventDimParm inventDimParm;
        InventDim     inventDim = _transferLine.inventDim();
        inventDimParm.initFromInventDim(inventDim);

        TmpInventTransMark transMark;
        InventUpdateMarking marking = new InventUpdateMarking();

        marking.updateMarking();

        _transferLine.metUpdateMarking(sourceTransferLineTransOriginId, transferLineTransOriginId, - _transferLine.QtyTransfer, - _transferLine.PdsCWQtyTransfer, inventDim, inventDimParm);

        ttscommit;
    }
}

/// <summary>
/// Initialize transfer order line from item details
/// </summary>
/// <param name = "_transLine"><t>InventTransferLine</t> table buffer to be initialized</param>
public void initTransferOrderLine(InventTransferLine _transLine)
{
    _transLine.ItemId = inventTransferLine.ItemId;
    _transLine.InventDimId = inventTransferLine.InventDimId;
    _transLine.initFromInventTable(InventTable::find(inventTransferLine.ItemId));

    super(_transLine);
}

/// <summary>
/// Should the order be auto-reserved
/// </summary>
/// <returns>true, if the order should be auto reserved otherwise false</returns>
public boolean shouldAutoReserve()
{
    boolean ret = false;

    return ret;
}

/// <summary>
/// Updates the CW quantity fields
/// </summary>
/// <param name = "_transferLine"><t>InventTransferLine</t> table buffer</param>
public void updatePDSQuantity(InventTransferLine _transferLine)
{
    _transferLine.PdsCWQtyTransfer = inventTransferLine.PdsCWQtyTransfer;
    _transferLine.modifiedField(fieldNum(InventTransferLine, PdsCWQtyTransfer));
}

/// <summary>
/// Update the source record with reference data
/// </summary>
public void updateSourceRecord(InventTransferLine _transferLine)
{
    metinventtransferline.selectForUpdate(true);
    metinventtransferline.TransferOrderNumber = finalLegTransferTable.TransferId;
    metinventtransferline.TransferLineTransId = _transferLine.InventTransIdReceive;
    metinventtransferline.OrderExtractStatus = METOrderExtractStatus::Extracted;

    metinventtransferline.update();
}
